import { z } from "zod";

/**
 * Strict output schemas for every LLM step. Outputs that fail validation are rejected
 * (one repair retry in the adapter), never "best-effort" parsed.
 * JSON Schema exports live in /schemas (generated by `npm run export:schemas`).
 */

const score = z.number().int().min(0).max(100);
const evidenceKind = z.enum(["FACT", "ESTIMATE", "INFERENCE"]);
const risk3 = z.enum(["LOW", "MEDIUM", "HIGH"]);

// ---------------------------------------------------------------- Concept extractor
export const ConceptExtractionSchema = z.object({
  concepts: z
    .array(
      z.object({
        name: z.string().min(2).max(60).describe("Normalized generic commercial concept, lowercase, no company names"),
        keywords: z.array(z.string().min(2).max(24)).min(1).max(6).describe("Core single words of the concept, lowercase"),
        description: z.string().max(300),
        commercial_rationale: z.string().max(400).describe("Why someone might pay for a name around this concept"),
        durability: z.enum(["DURABLE", "HYPE", "UNCLEAR"]),
        durability_reason: z.string().max(300),
        evidence_signal_ids: z.array(z.string()).min(1).describe("IDs of the provided signals that support this concept. Only IDs from the input."),
        merged_phrases: z.array(z.string()).describe("Input phrases grouped into this concept"),
        references_specific_company: z.boolean().describe("true if the concept is really about one company/product/trademark"),
        confidence: score,
      }),
    )
    .max(20),
  rejected_phrases: z
    .array(z.object({ phrase: z.string(), reason: z.string().max(160) }))
    .max(80),
});
export type ConceptExtraction = z.infer<typeof ConceptExtractionSchema>;

// ---------------------------------------------------------------- Domain lexicon (generator)
export const LexiconSchema = z.object({
  concepts: z.array(
    z.object({
      slug: z.string(),
      core_terms: z.array(z.string().regex(/^[a-z]{2,14}$/)).min(1).max(4),
      alt_nouns: z.array(z.string().regex(/^[a-z]{2,12}$/)).max(14).describe("Semantic alternatives / related nouns"),
      verbs: z.array(z.string().regex(/^[a-z]{2,10}$/)).max(10),
      brandable_roots: z.array(z.string().regex(/^[a-z]{3,12}$/)).max(10).describe("Short evocative roots, real words preferred"),
      avoid: z.array(z.string()).max(10).describe("Words to avoid: trademarks, negative connotations"),
    }),
  ),
});
export type Lexicon = z.infer<typeof LexiconSchema>;

// ---------------------------------------------------------------- Underwriter
const component = z.object({
  score,
  basis: evidenceKind,
  rationale: z.string().max(400),
});

export const UnderwriterSchema = z.object({
  domain: z.string(),
  verdict: z.enum(["INVEST", "WATCH", "REJECT"]),
  kill_reasons: z.array(z.string().max(200)).max(10).describe("Reasons this should NOT be bought. Empty only if none."),
  component_scores: z.object({
    demand_evidence: component,
    historical_market: component,
    buyer_universe: component,
    brandability: component,
    trend_momentum: component,
    tld_quality: component,
    capital_efficiency: component,
  }),
  confidence: score,
  confidence_rationale: z.string().max(400),
  trademark: z.object({ risk: risk3, rationale: z.string().max(300) }),
  thesis: z.string().max(600),
  why_now: z.string().max(400),
  risks: z.array(z.object({ risk: z.string().max(240), severity: risk3 })).min(1).max(8),
  evidence: z
    .array(
      z.object({
        claim: z.string().max(300),
        type: evidenceKind,
        fact_ids: z.array(z.string()).describe("Fact IDs (F#) from the fact sheet. Required for FACT claims."),
      }),
    )
    .max(12),
  estimated_retail: z
    .object({
      low: z.number().min(0),
      base: z.number().min(0),
      high: z.number().min(0),
      currency: z.literal("USD"),
      basis: z.string().max(300),
    })
    .nullable()
    .describe("ESTIMATE of an end-user retail price. null if there is not enough evidence."),
  potential_buyer_categories: z.array(z.string().max(80)).max(8),
});
export type UnderwriterOutput = z.infer<typeof UnderwriterSchema>;

// ---------------------------------------------------------------- Decisions (API input)
export const DecisionInputSchema = z.object({
  action: z.enum(["APPROVE", "REJECT", "WATCH", "BUY"]),
  reason: z.string().max(1000).optional().default(""),
  actor: z.string().max(60).optional(),
  human_or_agent: z.enum(["human", "agent"]).optional().default("human"),
  /** Only for BUY: what was actually paid when the purchase was executed manually, outside the system. */
  acquisition_cost: z.number().min(0).max(100000).optional(),
});
export type DecisionInput = z.infer<typeof DecisionInputSchema>;

export const SCHEMAS = {
  "concept-extraction.schema.json": ConceptExtractionSchema,
  "domain-lexicon.schema.json": LexiconSchema,
  "underwriter.schema.json": UnderwriterSchema,
  "decision-input.schema.json": DecisionInputSchema,
} as const;
